<?php $isContribution=$participation==='contribution';$formPhase=$isContribution?'registration':($isRegistration?'registration':'interest');$formParticipant=az_participant();$submitPurpose=$isContribution?'contribution':$formPhase; ?>
<dialog id="interest-dialog" class="interest-dialog" aria-labelledby="interest-title">
 <button class="dialog-close" aria-label="Close interest form">✕</button>
 <div id="interest-content"><h2 id="interest-title"><?= e($event[$isRegistration?'registration_title':'interest_title']) ?></h2><p class="dialog-intro"><?= e($event['title']) ?> · <?= cms_escape_lines($event[$isRegistration?'registration_intro':'interest_intro']??'') ?></p>
 <?php if(!$isContribution&&!$isRegistration): ?><p class="small-note">No sign-up or sign-in needed. Anyone can share their interest.</p><?php endif; ?>
 <form id="interest-form" method="post" enctype="multipart/form-data" action="/api/interest.php"><?= csrf_field() ?><input type="hidden" name="purpose" value="<?= $submitPurpose ?>"><input type="hidden" name="event" value="<?= e($slug) ?>">
 <label for="interest-name">Your name<input id="interest-name" name="name" required minlength="2" maxlength="100" autocomplete="name" value="<?= e($formParticipant['name']??'') ?>" <?= $formParticipant?'readonly':'' ?>></label>
 <label for="interest-email">Email address<input id="interest-email" name="email" type="email" required maxlength="254" autocomplete="email" value="<?= e($formParticipant['email']??'') ?>" <?= $formParticipant?'readonly':'' ?>></label>
 <?php $formGames=az_event_games($event);if($formGames): ?><label for="interest-game">Choose your game<select id="interest-game" name="game" required><option value="">Choose a game</option><?php foreach($formGames as $game): ?><option value="<?= e($game['id']) ?>"><?= e($game['label']) ?></option><?php endforeach; ?></select></label><?php endif; ?>
 <?php if($formGames): ?><div data-game-form data-event="<?= e($slug) ?>" data-phase="<?= e($formPhase) ?>"><p class="account-help" role="status">Choose a game to open its form.</p></div><?php else: az_registration_form($event,$formPhase); endif; ?>
 <label class="consent-label"><input type="checkbox" name="consent" value="yes" required><span>I agree that the Anazori organisers may store these details for this event and contact me about it.</span></label>
 <button type="submit" class="button button-orange"><?= e($event[$isRegistration?'registration_button':'interest_button']) ?> <?= arrow_icon() ?></button><p id="form-message" class="form-message" role="status" aria-live="polite"></p>
 </form></div>
 <div id="interest-success" hidden><span class="success-mark" aria-hidden="true">✓</span><h2><?= $isContribution?'Contribution sent.':($isRegistration?'Application received.':'Thanks for your interest.') ?></h2><p>Your details for <?= e($event['title']) ?> have been saved.</p><strong id="interest-reference" class="reference" <?= !$isRegistration||$isContribution?'hidden':'' ?>></strong><p class="small-note"><?= $isContribution?'The event team can contact you about your contribution.':($isRegistration?'The organisers will review your application.':'Thank you for sharing your interest.') ?></p><button class="button button-dark dialog-done">Back to exploring <?= arrow_icon() ?></button></div>
</dialog>
